import React, { useEffect, useState } from "react";
import ReactQuill from "react-quill";
import { useDispatch, useSelector } from "react-redux";
import {
  COUPONAdd,
  COUPONUpdate,
  SetCOUPONObj,
  CouponMultipleAdd,
} from "../../redux/actions/Coupon/Coupon.actions";
import CustomButton from "../Utility/Button";
import { generalModelStatuses } from "../Utility/constants";
import { DashboardBox } from "../Utility/DashboardBox";
import FileUpload from "../Utility/FileUpload";
import Select from "react-select";
import { generateFilePath } from "../Utility/utils";
import moment from "moment";
import { PRODUCTGet } from "../../redux/actions/Product/Product.actions";
import { toastError } from "../Utility/ToastUtils";
import { useNavigate } from "react-router-dom";
import Lottie from "react-lottie";
import animationData from "../Utility/loader1.json";
function AddCoupons() {
  const dispatch = useDispatch();
  const navigate = useNavigate();
  const productArr = useSelector((state) => state.product.products);

  const [name, setName] = useState("");
  const [description, setDescription] = useState("");
  const [value, setValue] = useState(0);
  const [validTill, setValidTill] = useState(new Date());
  const [maximumNoOfUsersAllowed, setMaximumNoOfUsersAllowed] = useState(0);
  const [discountType, setDiscountType] = useState("");
  const [selectedCouponId, setselectedCouponId] = useState("");
  const [image, setImage] = useState("");
  const [isUpdateBanner, setIsUpdateBanner] = useState(false);
  const bannerObj = useSelector((state) => state.coupon.couponObj);
  const [previousImage, setPreviousImage] = useState("");

  const [discountTypeArr, setDiscountTypeArr] = useState([
    { label: "PERCENTAGEOFF", value: "PERCENTAGEOFF" },
    { label: "AMOUNTOFF", value: "AMOUNTOFF" },
  ]);

  // Multiple  Coupon Add
  const [couponVal, setCouponVal] = useState("");
  const [totalCoupon, setTotalCoupon] = useState();
  const [coupons, setCoupons] = useState([{ value: 0, count: 0 }]);
  const [productId, setproductId] = useState("");
  const [productList, setproductList] = useState("");
  const [loading, setLoading] = useState(false);
  const handleFileSet = (value) => {
    setImage(value);
  };

  useEffect(() => {
    if (bannerObj) {
      setIsUpdateBanner(true);
    }
    return () => {
      dispatch(SetCOUPONObj(null));
    };
  }, [bannerObj]);

  useEffect(() => {
    dispatch(PRODUCTGet());
  }, []);
  useEffect(() => {
    if (productArr) {
      setproductList(productArr);
    }
  }, [productArr]);

  const handleSubmit = () => {
    let obj = {
      name,
      description,
      value,
      validTill: validTill,
      maximumNoOfUsersAllowed,
      discountType: discountType.value,
      image: image ? image : "",
    };

    if (isUpdateBanner) {
      dispatch(COUPONUpdate(obj, selectedCouponId));
    } else {
      dispatch(COUPONAdd(obj));
    }
  };

  const handleMultipleSubmitold = async () => {
    // Validate Product ID
    if (!productId || productId.trim() === "") {
      toastError("Please select a product.");
      return;
    }

    // Validate Total Coupon Value
    if (!couponVal || isNaN(couponVal) || couponVal <= 0) {
      toastError("Please enter a valid total coupon value.");
      return;
    }

    // Validate Total Coupon Count
    if (!totalCoupon || isNaN(totalCoupon) || totalCoupon <= 0) {
      toastError("Please enter a valid total coupon count.");
      return;
    }

    // Validate Coupons Array
    const invalidCoupons = coupons.some(
      (coupon) =>
        !coupon.value ||
        isNaN(coupon.value) ||
        coupon.value <= 0 ||
        !coupon.count ||
        isNaN(coupon.count) ||
        coupon.count <= 0
    );
    if (invalidCoupons) {
      toastError("Please ensure all coupon values and counts are valid.");
      return;
    }

    let obj = {
      amount: couponVal,
      count: totalCoupon,
      coupons,
      productId,
    };

    // Dispatch based on whether it's an update or new addition
    try {
      setLoading(true);
      if (isUpdateBanner) {
        await dispatch(COUPONUpdate(obj, selectedCouponId));
      } else {
        await dispatch(CouponMultipleAdd(obj));
        navigate("/Coupon/ViewCoupons");
      }
    } catch (error) {
      console.error("Error handling coupons:", error);
    } finally {
      setLoading(false); // Hide loader
    }
  };

  const handleMultipleSubmit = async () => {
    // Validate Product ID
    if (!productId || productId.trim() === "") {
      toastError("Please select a product.");
      return;
    }
  
    // Validate Total Coupon Value (allow 0)
    if (couponVal === undefined || isNaN(couponVal)) {
      toastError("Please enter a valid total coupon value.");
      return;
    }
  
    // Validate Total Coupon Count (must be greater than 0)
    if (!totalCoupon || isNaN(totalCoupon) || totalCoupon <= 0) {
      toastError("Total coupon count must be greater than 0.");
      return;
    }
  
    // Validate Coupons Array
    const invalidCoupons = coupons.some(
      (coupon) =>
        coupon.value === undefined || // Ensure value is defined
        isNaN(coupon.value) || // Ensure value is a number
        coupon.value < 0 || // Allow 0, but not negative
        coupon.count === undefined || // Ensure count is defined
        isNaN(coupon.count) || // Ensure count is a number
        coupon.count <= 0 // Count must be greater than 0
    );
  
    if (invalidCoupons) {
      toastError("Please ensure all coupon values and counts are valid. No of Coupons must be greater than 0.");
      return;
    }
  
    // Calculate the total value and count from the coupons array
    const totalCouponsValue = coupons.reduce(
      (sum, coupon) => sum + parseFloat(coupon.value) * parseInt(coupon.count),
      0
    );
    const totalCouponsCount = coupons.reduce(
      (sum, coupon) => sum + parseInt(coupon.count),
      0
    );
  
    // Validate that the total matches
    if (totalCouponsValue !== parseFloat(couponVal)) {
      toastError(
        `The total value of coupons (${totalCouponsValue}) must equal the Total Coupon Value (${couponVal}).`
      );
      return;
    }
  
    if (totalCouponsCount !== parseInt(totalCoupon)) {
      toastError(
        `The total count of coupons (${totalCouponsCount}) must equal the Total Coupon Count (${totalCoupon}).`
      );
      return;
    }
  
    let obj = {
      amount: couponVal,
      count: totalCoupon,
      coupons,
      productId,
    };
  
    // Dispatch based on whether it's an update or new addition
    try {
      setLoading(true);
      if (isUpdateBanner) {
        await dispatch(COUPONUpdate(obj, selectedCouponId));
      } else {
        await dispatch(CouponMultipleAdd(obj));
        navigate("/Coupon/ViewCoupons");
      }
    } catch (error) {
      console.error("Error handling coupons:", error);
    } finally {
      setLoading(false); // Hide loader
    }
  };
  
  let handleCouponArrayAdd = () => {
    setCoupons([...coupons, { value: "", count: "" }]);
  };

  let handleChangeCouponArr = (i, e) => {
    let newCoupons = [...coupons];
    newCoupons[i][e.target.name] = e.target.value;
    setCoupons(newCoupons);
  };

  let removeCouponFields = (i) => {
    let newCoupons = [...coupons];
    newCoupons.splice(i, 1);
    setCoupons(newCoupons);
  };

  const handleCoupnValueAdd = (event) => {
    if (discountType != "" && discountType.value == "PERCENTAGEOFF") {
      if (!(event.target.value > 100)) {
        setValue(event.target.value);
      } else {
        alert("cannot be more than 100");
        setValue(100);
      }
    } else {
      setValue(event.target.value);
    }
  };

  return (
    <main>
      <section className="product-category">
        <div className="container-fluid p-0">
          <h5 className="blue-1 mb-4">
            {isUpdateBanner ? "Update" : "Add New "} Coupon
          </h5>

          {loading ? (
            <div className="loader">
              <Lottie
                options={{
                  loop: true,
                  autoplay: true,
                  animationData: animationData, // Your animation JSON data
                }}
                height={70} // Adjust as needed
                width={70} // Adjust as needed
                style={{ margin: "15px" }}
              />
            </div>
          ) : (
            <form action="#" className="form">
              {/* Multiple Coupon Create */}

              <div className="row">
                <div className="col-12 col-md-8 mb-0">
                  <DashboardBox>
                    <div className="row">
                      <h5 className="blue-1 mb-4">Coupon Information</h5>
                      <div className="col-md-12">
                        <label>
                          Product List <span className="red">*</span>
                        </label>
                        <select
                          className="form-control"
                          value={productId}
                          onChange={(e) => {
                            setproductId(e.target.value);
                          }}
                        >
                          <option value="">Please Select Product</option>
                          {productList &&
                            productList.map((product) => (
                              <option value={product?._id}>
                                {product?.name}
                              </option>
                            ))}
                        </select>
                      </div>
                      <div className="col-md-6">
                        <label>
                          Total Coupon Value <span className="red">*</span>
                        </label>
                        <input
                          value={couponVal}
                          onChange={(event) => setCouponVal(event.target.value)}
                          type="text"
                          className="form-control"
                        />
                      </div>
                      <div className="col-md-6">
                        <label>
                          No of Coupon <span className="red">*</span>
                        </label>
                        <input
                          value={totalCoupon}
                          name="count"
                          onChange={(event) =>
                            setTotalCoupon(event.target.value)
                          }
                          type="text"
                          className="form-control"
                        />
                      </div>

                      <div className="col-md-12">
                        <h6 className="blue-1 my-2">Coupons</h6>
                        {coupons.map((element, index) => (
                          <div className="row" key={index}>
                            <div className="col-md-4">
                              <label>
                                Coupon Value <span className="red">*</span>{" "}
                              </label>
                              <input
                                name="value"
                                type="text"
                                value={element.value}
                                onChange={(e) =>
                                  handleChangeCouponArr(index, e)
                                }
                                className="form-control"
                                required
                              />
                            </div>
                            <div className="col-md-4">
                              <label>
                                No of Coupon <span className="red">*</span>{" "}
                              </label>

                              <input
                                name="count"
                                type="number"
                                value={element.count}
                                min="0"
                                onChange={(e) =>
                                  handleChangeCouponArr(index, e)
                                }
                                className="form-control"
                                required
                              />
                            </div>

                            {index ? (
                              <div className="col-md-2">
                                <button
                                  className="btn btn-danger btn-sm mt-4"
                                  onClick={() => removeCouponFields(index)}
                                >
                                  <i className="fa-solid fa-trash"> </i>{" "}
                                </button>
                              </div>
                            ) : null}
                          </div>
                        ))}
                      </div>
                      <div className="col-md-4">
                        <button
                          type="button"
                          className="btn btn-secondary btn-sm"
                          onClick={handleCouponArrayAdd}
                        >
                          <i className="fa-solid fa-plus"> </i> Add
                        </button>
                      </div>
                      <div className="col-12 mt-2">
                        <CustomButton
                          btntype="button"
                          ClickEvent={handleMultipleSubmit}
                          isBtn
                          iconName="fa-solid fa-check"
                          btnName="Save"
                        />
                      </div>
                    </div>
                  </DashboardBox>
                </div>
              </div>

              {/* Single Add Coupon  */}

              {/* <div className="row">
              <div className="col-12 col-md-8 mb-0">
                <DashboardBox>
                  <div className="row">
                    <h5 className="blue-1 mb-4">Coupon Information</h5>
                    <div className="col-12">
                      <label>
                        Name <span className="red">*</span>
                      </label>
                      <input value={name} onChange={(event) => setName(event.target.value)} type="text" className="form-control" />
                    </div>
                    <div className="col-12">
                      <label>Description</label>
                      <ReactQuill value={description} onChange={(event) => setDescription(event)} theme="snow" />
                    </div>
                    <div className="col-12">
                      <label>
                        Value <span className="red">*</span>
                      </label>
                      <input value={value} onChange={(event) => { handleCoupnValueAdd(event) }} type="number" className="form-control" />
                    </div>
                    <div className="col-12">
                      <label>
                        Valid Till <span className="red">*</span>
                      </label>
                      <input value={moment(validTill).format("YYYY-MM-DD")} onChange={(event) => setValidTill(event.target.value)} type="date" className="form-control" />
                    </div>
                    <div className="col-12">
                      <label>
                        Maximum No Of Users Allowed <span className="red">*</span>
                      </label>
                      <input value={maximumNoOfUsersAllowed} onChange={(event) => setMaximumNoOfUsersAllowed(event.target.value)} type="number" className="form-control" />
                    </div>
                    <div className="col-12 col-md-12">
                      <label>
                        Discount Type <span className="red">*</span>
                      </label>
                      <Select
                        options={discountTypeArr}
                        placeholder="Select from options"
                        defaultInputValue={discountType}
                        value={discountType}
                        onChange={(e) => {
                    
                          if (e.value == "PERCENTAGEOFF") {
                            if (value != 0 && value > 100) {
                              setValue(100)
                            }
                          }
                          setDiscountType(e)
                        }
                        }
                      />
                    </div>

                  </div>
                </DashboardBox>
              </div>
              <div className="col-12 col-md-4 mb-0">
                <DashboardBox>
                  <div className="row">
                    <h5 className="blue-1 mb-4">Status Info</h5>
                    <div className="col-12">
                      <label>Banner (150x150)PX</label>
                      <FileUpload onFileChange={handleFileSet} />
                    </div>
                    {
                      previousImage != "" &&
                      <img src={generateFilePath(previousImage)} style={{ width: 200, height: 100 }} alt="" />
                    }
                    <div className="col-12 mt-2">
                      <CustomButton btntype="button" ClickEvent={handleSubmit} isBtn iconName="fa-solid fa-check" btnName="Save" />
                    </div>
                  </div>
                </DashboardBox>
              </div>
            </div> */}
            </form>
          )}
        </div>
      </section>
    </main>
  );
}

export default AddCoupons;
